findings.current:
.button {
  transition:
    background-color var(--hx-transition-fast, 150ms ease),
    color var(--hx-transition-fast, 150ms ease),
    border-color var(--hx-transition-fast, 150ms ease),
    box-shadow var(--hx-transition-fast, 150ms ease);
}

@media (prefers-reduced-motion: reduce) {
  .button__spinner {
    animation: none;
    opacity: var(--hx-opacity-muted, 0.6);
  }
}

findings.fix:
@media (prefers-reduced-motion: reduce) {
  .button {
    transition: none;
  }
  .button__spinner {
    animation: none;
    opacity: var(--hx-opacity-muted, 0.6);
  }
}

findings.current:
.alert__close-button {
  transition:
    opacity var(--hx-transition-fast, 150ms ease),
    background-color var(--hx-transition-fast, 150ms ease);
}

.link {
  transition:
    color var(--hx-transition-fast, 150ms ease),
    text-decoration-color var(--hx-transition-fast, 150ms ease),
    box-shadow var(--hx-transition-fast, 150ms ease);
}

.step__indicator {
  transition:
    background-color var(--hx-transition-fast, 150ms ease),
    border-color var(--hx-transition-fast, 150ms ease),
    color var(--hx-transition-fast, 150ms ease);
}

.step__connector {
  transition: background-color var(--hx-transition-fast, 150ms ease);
}

.code-snippet__copy-button {
  transition:
    background-color var(--hx-transition-fast, 150ms ease),
    color var(--hx-transition-fast, 150ms ease),
    opacity var(--hx-transition-fast, 150ms ease);
}

.code-snippet__expand-button {
  transition: color var(--hx-transition-fast, 150ms ease);
}

.field__textarea-wrapper {
  transition:
    border-color var(--hx-transition-fast, 150ms ease),
    box-shadow var(--hx-transition-fast, 150ms ease);
}

.dialog__close-btn {
  transition:
    background-color var(--hx-transition-fast, 150ms ease),
    opacity var(--hx-transition-fast, 150ms ease);
}

.menu-item {
  transition: background-color var(--hx-transition-fast, 150ms ease);
}
.menu-item__checked-icon {
  transition: opacity var(--hx-transition-fast, 150ms ease);
}
@media (prefers-reduced-motion: reduce) {
  .menu-item__spinner { ... }
}

tbody tr {
  transition: background-color var(--hx-transition-fast, 150ms ease);
}
.sort-icon {
  transition:
    opacity var(--hx-transition-fast, 150ms ease),
    transform var(--hx-transition-fast, 150ms ease);
}

findings.fix:
@media (prefers-reduced-motion: reduce) {
  tbody tr,
  .sort-icon,
  .skeleton__shimmer {
    transition: none;
  }
  .skeleton__shimmer {
    animation: none;
  }
}

findings.current:
.side-nav__toggle {
  transition:
    background-color var(--hx-transition-fast, 150ms ease),
    color var(--hx-transition-fast, 150ms ease);
}

.field__trigger { transition: border-color ..., box-shadow ...; }
.calendar__nav-btn { transition: background-color ..., color ...; }
.calendar__day { transition: background-color ..., color ...; }

.progress-bar__fill {
  transition: width 0.2s ease;
}
@keyframes progress-bar-indeterminate {
  0% { width: 30%; left: -30%; }
  100% { width: 30%; left: 100%; }
}

findings.fix:
.progress-bar__fill {
  transform-origin: left;
  transition: transform var(--hx-transition-normal, 250ms ease);
}
/* Set transform: scaleX(value/max) via CSS custom property from JS */

@keyframes progress-bar-indeterminate {
  0% { transform: translateX(-130%); }
  100% { transform: translateX(400%); }
}

findings.current:
.nav-item__label {
  transition: width var(--hx-transition-fast, 150ms ease);
}
.nav-item__children {
  transition: max-height var(--hx-transition-normal, 250ms ease);
}

findings.fix:
.nav-item__label {
  transition: opacity var(--hx-transition-fast, 150ms ease);
  /* Use clip-path or overflow hidden for collapse */
}
.nav-item__children {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--hx-transition-normal, 250ms ease);
}
.nav-item__children--expanded {
  grid-template-rows: 1fr;
}

.progress-bar {
  transform-origin: left;
  transition: transform var(--hx-transition-normal, 250ms ease);
}
/* Set transform: scaleX(progress/100) via CSS custom property */
:host { --_progress: 0; }
.progress-bar { transform: scaleX(var(--_progress)); }

.slider__fill {
  transform-origin: left;
  transition: transform var(--hx-transition-fast, 150ms ease);
}

.meter__indicator {
  transform-origin: left;
  transition: transform var(--hx-transition-normal, 250ms ease);
}

.dropdown-menu {
  transition:
    opacity var(--hx-transition-fast, 150ms ease),
    visibility var(--hx-transition-fast, 150ms ease);
}

findings.current:
.spinner__svg {
  animation: hx-spinner-rotate 2s linear infinite;
}
.spinner__circle {
  animation: hx-spinner-dash 1.5s ease-in-out infinite;
}

findings.fix:
.spinner__svg {
  animation: hx-spinner-rotate var(--hx-spinner-rotate-duration, 2s) linear infinite;
}
.spinner__circle {
  animation: hx-spinner-dash var(--hx-spinner-dash-duration, 1.5s) ease-in-out infinite;
}

.step:focus-visible .step__indicator {
  outline: var(--hx-focus-ring-width, 2px) solid
    var(--hx-focus-ring-color, var(--hx-color-primary-500));
  outline-offset: var(--hx-focus-ring-offset, 2px);
}

findings.current:
.field__chip-remove {
  transition:
    color var(--hx-transition-fast, 150ms ease),
    opacity var(--hx-transition-fast, 150ms ease);
}

.toast {
  opacity: 0;
  transform: translateY(...);
  transition: opacity ..., transform ...;
}

findings.fix:
.toast {
  will-change: opacity, transform;
  /* Remove will-change after animation completes via JS if needed */
}

findings.current:
.dialog__panel {
  opacity: 0;
  transform: scale(0.95);
  transition: opacity ..., transform ...;
}

findings.fix:
@media (prefers-color-scheme: dark) {
  .step__connector-line { ... }
  .step__indicator { border-color: var(--hx-color-neutral-600); }
  .step__label { color: var(--hx-color-neutral-200); }
  .step__description { color: var(--hx-color-neutral-400); }
}

.divider:focus-visible {
  box-shadow: 0 0 0 var(--hx-focus-ring-spread, 4px) color-mix(in srgb, var(--_divider-hover-color) 30%, transparent);
}
